def simulateQueue(commands: list) -> list:
    in_stack = []
    out_stack = []
    results = []
    for cmd in commands:
        op = cmd[0]
        if op == 'push':
            in_stack.append(cmd[1])
        elif op == 'pop':
            if not out_stack:
                while in_stack:
                    out_stack.append(in_stack.pop())
            results.append(out_stack.pop())
        elif op == 'peek':
            if not out_stack:
                while in_stack:
                    out_stack.append(in_stack.pop())
            results.append(out_stack[-1])
        elif op == 'empty':
            results.append(len(in_stack) == 0 and len(out_stack) == 0)
    return results

